fn arccosh(x: Vec<f32>) -> Vec<f32> {
    // Pre-allocate the output vector with the same length as input.
    let mut result = Vec::with_capacity(x.len());

    // Process each element by index, from 0 to x.len() - 1.
    for i in 0..x.len() {
        // Apply the acosh transformation and push into the result.
        result.push(x[i].acosh());
    }

    result
}

